1	type Item = { type: string; material?: string; cursed?: boolean; enchantment?: number };
2	
3	const basePremiumsByType: Record<string, number> = { sword: 100, amulet: 60, staff: 80, potion: 40, rune: 25, moonstone: 25 };
4	
5	const BLOCK_SIZE = 3;
6	const BLOCK_PREMIUM = 60;
7	
8	const sumBy = <T>(values: T[], valueOf: (value: T) => number): number =>
9	  values.reduce((sum, value) => sum + valueOf(value), 0);
10	
11	const basePremiumForItem = (item: Item): number => basePremiumsByType[item.type];
12	
13	const sumOfItemBasePremiums = (items: Item[]): number =>
14	  sumBy(items, basePremiumForItem);
15	
16	const groupByType = (items: Item[]): Item[][] => {
17	  const groups = new Map<string, Item[]>();
18	  for (const item of items) {
19	    const group = groups.get(item.type) ?? [];
20	    group.push(item);
21	    groups.set(item.type, group);
22	  }
23	  return [...groups.values()];
24	};
25	
26	const basePremiumForGroup = (group: Item[]): number =>
27	  group.length === BLOCK_SIZE ? BLOCK_PREMIUM : sumOfItemBasePremiums(group);
28	
29	export const basePremium = (items: Item[]): number =>
30	  sumBy(groupByType(items), basePremiumForGroup);
31	
32	const PROCESSING_FEE = 5;
33	
34	type Customer = { yearsWithMHPCO: number };
35	type QuoteStep = { op: "quote"; items: Item[] };
36	type Damage = { itemType: string; amount: number };
37	type ClaimStep = { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
38	type Step = QuoteStep | ClaimStep;
39	type Scenario = { customer: Customer; steps: Step[] };
40	
41	type QuoteResult = { premium: number };
42	type ClaimResult = { payout: number; remainingCap: number };
43	type StepResult = QuoteResult | ClaimResult;
44	
45	const CURSE_SURCHARGE_RATE = 0.5;
46	const HIGH_ENCHANTMENT_RATE = 0.3;
47	const HIGH_ENCHANTMENT_THRESHOLD = 5;
48	const FIRST_INSURANCE_RATE = 0.1;
49	const LOYALTY_RATE = 0.2;
50	const LOYALTY_THRESHOLD = 2;
51	const FOLLOWUP_RATE = 0.15;
52	
53	const surchargeOf = (item: Item, rate: number): number => basePremiumForItem(item) * rate;
54	
55	const curseSurchargeForItem = (item: Item): number =>
56	  item.cursed ? surchargeOf(item, CURSE_SURCHARGE_RATE) : 0;
57	
58	const curseSurcharge = (items: Item[]): number =>
59	  sumBy(items, curseSurchargeForItem);
60	
61	const highEnchantmentSurchargeForItem = (item: Item): number =>
62	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
63	    ? surchargeOf(item, HIGH_ENCHANTMENT_RATE)
64	    : 0;
65	
66	const highEnchantmentSurcharge = (items: Item[]): number =>
67	  sumBy(items, highEnchantmentSurchargeForItem);
68	
69	const rateOfPolicyBase = (policyBase: number, rate: number): number => policyBase * rate;
70	
71	const firstInsuranceSurcharge = (policyBase: number): number =>
72	  rateOfPolicyBase(policyBase, FIRST_INSURANCE_RATE);
73	
74	const loyaltyDiscount = (policyBase: number, customer: Customer): number =>
75	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD ? rateOfPolicyBase(policyBase, LOYALTY_RATE) : 0;
76	
77	const followUpDiscount = (policyBase: number, isFollowUp: boolean): number =>
78	  isFollowUp ? rateOfPolicyBase(policyBase, FOLLOWUP_RATE) : 0;
79	
80	const itemSurcharges = (items: Item[]): number =>
81	  curseSurcharge(items) + highEnchantmentSurcharge(items);
82	
83	// The premium is rounded up so any fraction lands in MHPCO's favor.
84	const roundPremiumInFavorOfMHPCO = (premium: number): number => Math.ceil(premium);
85	
86	const quotePremium = (step: QuoteStep, customer: Customer, isFollowUp: boolean): number => {
87	  const policyBase = basePremium(step.items);
88	  const surcharges = itemSurcharges(step.items) + firstInsuranceSurcharge(policyBase);
89	  const discounts = loyaltyDiscount(policyBase, customer) + followUpDiscount(policyBase, isFollowUp);
90	  return roundPremiumInFavorOfMHPCO(policyBase + surcharges - discounts + PROCESSING_FEE);
91	};
92	
93	const DEDUCTIBLE = 100;
94	const CAP_MULTIPLIER = 2;
95	const REDUCED_REIMBURSEMENT_THRESHOLD = 8;
96	const REDUCED_REIMBURSEMENT_RATE = 0.5;
97	
98	const insuranceValuesByType: Record<string, number> = { sword: 1000, amulet: 600, staff: 800, potion: 400, rune: 250, moonstone: 250 };
99	
100	const insuranceValue = (item: Item): number => insuranceValuesByType[item.type];
101	
102	const insuranceSum = (items: Item[]): number =>
103	  sumBy(items, insuranceValue);
104	
105	const reimbursedAmount = (damage: Damage, item: Item): number =>
106	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_THRESHOLD
107	    ? damage.amount * REDUCED_REIMBURSEMENT_RATE
108	    : damage.amount;
109	
110	const payoutForDamage = (damage: Damage, items: Item[]): number => {
111	  const item = items.find((candidate) => candidate.type === damage.itemType) as Item;
112	  return reimbursedAmount(damage, item) - DEDUCTIBLE;
113	};
114	
115	const claimResult = (step: ClaimStep, scenario: Scenario): ClaimResult => {
116	  const policy = scenario.steps[step.policy] as QuoteStep;
117	  const cap = insuranceSum(policy.items) * CAP_MULTIPLIER;
118	  const payout = sumBy(step.incident.damages, (damage) => payoutForDamage(damage, policy.items));
119	  return { payout, remainingCap: cap - payout };
120	};
121	
122	export const runScenario = (scenario: Scenario): { results: StepResult[] } => ({
123	  results: scenario.steps.map((step, index) =>
124	    step.op === "quote"
125	      ? { premium: quotePremium(step, scenario.customer, index > 0) }
126	      : claimResult(step, scenario),
127	  ),
128	});
